mapper.select:
SELECT ExitDate as staDate, StationID as stationId, OperatorID as operatorId, EntryLane as entryLane, LaneID as laneId, ExitTime as exitTime, LicensePlate as licensePlate, TollFee / 100 as tollfee FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND StationID in
#{stationId}
AND ExitDate >= #{intBeginTime}
AND ExitDate <= #{intEndTime}
AND CancelFlag = 0 AND VehicleStatus=102 AND RecordType&1=1
a ORDER BY ExitTime

SELECT OperatorName as operatorName, OperatorID as operatorId FROM dbtoms.tboperatorinfo
AND OperatorID in
#{operatorId}

SELECT StationName as stationName, StationID as stationId FROM dbtoms.tbstationinfo
AND StationID in
#{stationId}
